def get_drop_filter_category(template_id: str) -> str:
    """Klassifiziert ein Item für das Auto-Pick-Up Drop-Filter-System (Projekt 1 Standard):
    'weapons' | 'armors' | 'jewelry' | 'upgradeItems' | 'skillBooks' | 'runesAndScrolls' | 'potions' | 'chests'
    """
    tpl = ITEM_TEMPLATES.get(template_id, {})
    itype = tpl.get("type", "equipment")
    slot = tpl.get("slot", "")
    if itype == "equipment":
        if slot in ("weapon", "costume_weapon"):
            return "weapons"
        if slot in ("armor", "costume", "costume_armor"):
            return "armors"
        return "jewelry"
    if itype == "chest":
        return "chests"
    if itype == "consumable":
        return "potions"
    if template_id in ("book_skill", "mat_soul_stone", "item_soul_fragment"):
        return "skillBooks"
    if template_id in (
        "scroll_blessing",
        "item_magic_metal",
        "item_bonus_adder",
        "item_bonus_changer",
        "item_aether_seal",
    ):
        return "runesAndScrolls"
    return "upgradeItems"


