    {"id": "bonus_vs_metin", "name": "Stark gegen Rissmonolythen", "unit": "%", "tiers": [(8, 30), (15, 15), (25, 5)]},
    {"id": "bonus_vs_boss", "name": "Stark gegen Bosse", "unit": "%", "tiers": [(8, 30), (15, 15), (25, 5)]},
