# 8. MOUNTS & PETS (Kap. 12) - Pferde-System Lv. 1–50, Mount-Skins & Pet-System
# ============================================================================
MAX_HORSE_LEVEL = 50


def get_required_horse_medals(level: int) -> int:
    """Berechnet die benötigten Pferdemedaillen für den Aufstieg von Pferde-Stufe `level` auf `level + 1` (Max. Lv. 50)."""
    lv = max(1, min(MAX_HORSE_LEVEL, int(level or 1)))
    if lv < 15:
        return 1
    if lv < 30:
        return 2
    if lv < 35:
        return 3
    if lv < 42:
        return 4
    if lv < 48:
        return 5
    if lv == 48:
        return 6
    return 8


