# ============================================================================
# 8C. PET-SYSTEM FERTIGKEITEN (Aktiv Lv. 1-5 & Passiv Lv. 1-20 aus Projekt 1)
# ============================================================================
MAX_PET_LEVEL = 120
MAX_PET_STAT_POINTS = 120


def get_required_pet_exp(level: int) -> int:
    lvl = max(1, int(level))
    if lvl <= 1:
        return 300
    if lvl >= MAX_PET_LEVEL:
        return 500000000
    exp_val = 300.0 * (1.062 ** (lvl - 1)) + (lvl * lvl * 120.0)
    return max(300, min(500000000, int(exp_val)))


