def exp_needed_for_level(level: int) -> int:
    """Benötigte EXP für den Aufstieg vom angegebenen Level (SSOT Ultimate Edition):
      - Lv. 1  → 20: exakt 40–60 Minuten (~50 Min)
      - Lv. 21 → 30: exakt 40–60 Minuten (~50 Min)
      - Lv. 31 → 35: exakt 40–60 Minuten (~50 Min)
      - Lv. 35 → 38: exakt 60 Minuten
      - Ab Lv. 38  : kaum noch EXP in Map 1 & Map 2
    """
    level = max(1, int(level))
    table = _get_level_exp_table()
    if level in table:
        return table[level]
    return int(_target_minutes_for_level(level) * _expected_exp_per_minute(level))


# Angenommene Kill-Rate beim Auto-Jagen im passenden Gebiet (inkl. Laufwege) & Zusatz-EXP aus Quests/Monolithen/Bossen
LEVEL_CURVE_KILLS_PER_MIN = 7.0
LEVEL_CURVE_EXTRA_EXP_FACTOR = 1.25
_LEVEL_EXP_TABLE_CACHE: dict = {}


def _target_minutes_for_level(level: int) -> float:
    """Zielminuten für genau EIN Level-Up (Level → Level+1) strikt nach SSOT-Handbuch."""
    if level < 20:
        return 1.73 + (level - 1) * 0.10     # Summe Lv. 1→20 = 49.97 Min (exakt im Fenster 40–60 Min)
    if level < 30:
        return 4.10 + (level - 20) * 0.20    # Summe Lv. 20→30 = 50.00 Min (exakt im Fenster 40–60 Min)
    if level < 35:
        return 8.40 + (level - 30) * 0.80    # Summe Lv. 30→35 = 50.00 Min (exakt im Fenster 40–60 Min)
    if level < 38:
        return 18.0 + (level - 35) * 2.0     # Summe Lv. 35→38 = 60.00 Min (exakt 60 Min)
    return 35.0 + (level - 38) * 4.5         # Ab Lv. 38 steiler + 98% Map-EXP-Dämpfung in Map 1/2


def _expected_exp_per_minute(level: int) -> float:
    """Erwartete EXP/Minute aus den Monster-Templates.

    Über alle normalen Monster wird eine glatte Potenzkurve EXP(Level) = a · Level^b gefittet (Log-Regression),
    damit die Levelkurve monoton & ohne Sprünge verläuft – auch für Level ohne eigene Monster.
    """
    a_b = _LEVEL_EXP_TABLE_CACHE.get("_fit")
    if a_b is None:
        pts = [
            (int(t.get("level", 1) or 1), float(t.get("exp", 0) or 0))
            for t in MONSTER_TEMPLATES.values()
            if not t.get("isBoss") and t.get("kind") != "metin" and not t.get("isElite") and float(t.get("exp", 0) or 0) > 0
        ]
        if len(pts) >= 3:
            xs = [math.log(max(1, l)) for l, _ in pts]
            ys = [math.log(e) for _, e in pts]
            mx = sum(xs) / len(xs)
            my = sum(ys) / len(ys)
            den = sum((x - mx) ** 2 for x in xs) or 1.0
            b = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / den
            a = math.exp(my - b * mx)
        else:
            a, b = 30.0, 1.16
        a_b = (a, b)
        _LEVEL_EXP_TABLE_CACHE["_fit"] = a_b
    a, b = a_b
    mob_exp = a * math.pow(max(1, level), b)
    # 0.26 = EXP-Faktor pro Kill aus WorldAuthority (tpl["exp"] * 0.26)
    return mob_exp * 0.26 * LEVEL_CURVE_KILLS_PER_MIN * LEVEL_CURVE_EXTRA_EXP_FACTOR


def _get_level_exp_table() -> dict:
    if 1 not in _LEVEL_EXP_TABLE_CACHE:
        for lvl in range(1, 121):
            _LEVEL_EXP_TABLE_CACHE[lvl] = max(100, int(round(_target_minutes_for_level(lvl) * _expected_exp_per_minute(lvl), -1)))
    return _LEVEL_EXP_TABLE_CACHE


def calculate_item_effective_stats(template_id: str, plus_level: int = 0, bonuses: list = None) -> dict:
    """Zentrale serverseitige Berechnung der effektiven Werte eines Gegenstands inkl. +0 bis +9, Geiststeinen und Runenboni."""
    tpl = ITEM_TEMPLATES.get(template_id)
    if not tpl:
        return {}
    base = dict(tpl.get("baseStats", {}))
    max9 = tpl.get("maxStats9")
    p_lvl = max(0, min(9, int(plus_level or 0)))
    result = {}

    if isinstance(max9, dict) and max9:
        frac = p_lvl / 9.0
        for k, v0 in base.items():
            v9 = max9.get(k, v0)
            val = v0 + (v9 - v0) * frac
            if isinstance(v0, int) and isinstance(v9, int):
                result[k] = int(round(val))
            else:
                result[k] = round(val, 1)
    else:
        plus_mult = 1.0
        if p_lvl > 0:
            rate_row = BLACKSMITH_RATES.get(min(8, p_lvl - 1))
            if rate_row:
                plus_mult = rate_row["statMult"]
        eff_plus_mult = 1.0 + (plus_mult - 1.0) * 0.45
        for k, v in base.items():
            if k in ("atk", "magicAtk", "def", "magicDef", "hp"):
                result[k] = int(round(v * eff_plus_mult))
            else:
                result[k] = round(v * (1.0 + p_lvl * 0.04), 1)

    for b in (bonuses or []):
        bid = b.get("id")
        val = b.get("value", 0)
        if bid == "socket_stone":
            st_stat = b.get("stoneStat")
            if not st_stat and b.get("stoneId"):
                st_tpl = ITEM_TEMPLATES.get(b.get("stoneId")) or {}
                st_stat = st_tpl.get("stoneStat")
                val = val or st_tpl.get("stoneValue", 0)
            if st_stat:
                result[st_stat] = result.get(st_stat, 0) + val
            continue
        if bid == "bonus_hp":
            result["hp"] = result.get("hp", 0) + val
        elif bid == "bonus_atk":
            result["atk"] = result.get("atk", 0) + val
        elif bid == "bonus_crit":
            result["critChance"] = result.get("critChance", 0) + val
        elif bid == "bonus_pierce":
            result["pierceChance"] = result.get("pierceChance", 0) + val
        elif bid == "bonus_vs_metin":
            result["vsMetinPct"] = result.get("vsMetinPct", 0) + val
        elif bid == "bonus_vs_monster":
            result["vsMonsterPct"] = result.get("vsMonsterPct", 0) + val
        elif bid == "bonus_vs_devil":
            result["vsDevilPct"] = result.get("vsDevilPct", 0) + val
        elif bid == "bonus_vs_undead":
            result["vsUndeadPct"] = result.get("vsUndeadPct", 0) + val
        elif bid == "bonus_vs_orcs":
            result["vsOrcsPct"] = result.get("vsOrcsPct", 0) + val
        elif bid == "bonus_vs_animals":
            result["vsAnimalsPct"] = result.get("vsAnimalsPct", 0) + val
